-- Apply in Supabase SQL Editor. Only SECURITY DEFINER RPCs mutate game state.
create extension if not exists pgcrypto;
create type public.game_phase as enum ('lobby','night','discussion','voting','summary','game_over');
create type public.game_role as enum ('virologist','surgeon','infected','researcher','resident');
create table public.rooms (id uuid primary key default gen_random_uuid(), code text unique not null check (code ~ '^[A-Z0-9]{4,12}$'), host_key_hash text not null, phase public.game_phase not null default 'lobby', phase_ends_at timestamptz, day_number int not null default 0, morning_log jsonb not null default '[]', created_at timestamptz not null default now());
create table public.players (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, display_name text not null, seat smallint not null check(seat between 1 and 36), role public.game_role, is_alive boolean not null default true, session_token uuid not null default gen_random_uuid(), joined_at timestamptz not null default now(), unique(room_id,seat), unique(room_id,session_token));
create table public.intents (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, actor_id uuid not null references public.players(id) on delete cascade, target_id uuid not null references public.players(id), phase public.game_phase not null, kind text not null check(kind in ('action','vote')), locked_at timestamptz not null default now(), unique(room_id,actor_id,phase,kind));
alter table public.rooms enable row level security; alter table public.players enable row level security; alter table public.intents enable row level security;
-- No direct browser table policies. The anon client can only call execute-granted RPCs.
create or replace function public.public_room_snapshot(p_code text) returns jsonb language sql security definer set search_path=public as $$
 select jsonb_build_object('room',jsonb_build_object('id',r.id,'code',r.code,'phase',r.phase,'phase_ends_at',r.phase_ends_at,'day_number',r.day_number,'morning_log',r.morning_log),'players',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'display_name',p.display_name,'seat',p.seat,'is_alive',p.is_alive,'has_acted',exists(select 1 from intents i where i.actor_id=p.id and i.phase=r.phase and i.kind='action'),'has_voted',exists(select 1 from intents i where i.actor_id=p.id and i.phase=r.phase and i.kind='vote')) order by p.seat) from players p where p.room_id=r.id),'[]'::jsonb)) from rooms r where r.code=upper(p_code); $$;
create or replace function public.join_room(p_code text,p_name text) returns jsonb language plpgsql security definer set search_path=public as $$ declare r rooms; p players; begin select * into r from rooms where code=upper(p_code) for update; if not found then raise exception 'Room not found'; end if; if r.phase <> 'lobby' then raise exception 'Admissions are closed'; end if; insert into players(room_id,display_name,seat) values(r.id,p_name,(select coalesce(min(s),37) from generate_series(1,36)s where not exists(select 1 from players where room_id=r.id and seat=s))) returning * into p; if p.seat=37 then raise exception 'Room is full'; end if; return jsonb_build_object('sessionToken',p.session_token,'player',jsonb_build_object('id',p.id,'display_name',p.display_name,'seat',p.seat,'is_alive',p.is_alive)); end $$;
create or replace function public.submit_intent(p_code text,p_session uuid,p_target uuid,p_kind text) returns boolean language plpgsql security definer set search_path=public as $$ declare r rooms; actor players; target players; begin select * into r from rooms where code=upper(p_code); select * into actor from players where room_id=r.id and session_token=p_session; select * into target from players where id=p_target and room_id=r.id; if not found or actor.id is null or not actor.is_alive or not target.is_alive then raise exception 'Invalid actor or target'; end if; if (p_kind='vote' and r.phase<>'voting') or (p_kind='action' and (r.phase<>'night' or actor.role='resident')) then raise exception 'Terminal unavailable for this role or phase'; end if; insert into intents(room_id,actor_id,target_id,phase,kind) values(r.id,actor.id,target.id,r.phase,p_kind) on conflict(room_id,actor_id,phase,kind) do update set target_id=excluded.target_id,locked_at=now(); return true; end $$;
create or replace function public.my_dossier(p_code text,p_session uuid) returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('id',p.id,'display_name',p.display_name,'seat',p.seat,'is_alive',p.is_alive,'role',p.role) from players p join rooms r on r.id=p.room_id where r.code=upper(p_code) and p.session_token=p_session $$;
create or replace function public.host_transition(p_code text,p_host_key text,p_phase public.game_phase,p_minutes int default null) returns void language plpgsql security definer set search_path=public as $$ declare r rooms; begin select * into r from rooms where code=upper(p_code) for update; if not found or crypt(p_host_key,r.host_key_hash)<>r.host_key_hash then raise exception 'Unauthorized host command'; end if; if p_phase='night' and r.phase='lobby' then if (select count(*) from players where room_id=r.id)<>36 then raise exception 'Need exactly 36 players'; end if; with ranked as (select id,row_number() over(order by random()) n from players where room_id=r.id) update players p set role=case when n<=3 then 'virologist'::game_role when n<=6 then 'surgeon'::game_role when n<=14 then 'infected'::game_role when n<=18 then 'researcher'::game_role else 'resident'::game_role end from ranked x where p.id=x.id; end if; update rooms set phase=p_phase,phase_ends_at=case when p_minutes is null then null else now()+make_interval(mins=>p_minutes) end,day_number=case when p_phase='night' then day_number+1 else day_number end where id=r.id; end $$;
grant execute on function public.public_room_snapshot(text) to anon, authenticated;
